def transform(grid):
    h, w = len(grid), len(grid[0])

    divider_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    divider_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    # The uniform full-length lines are dividers; the most common remaining
    # color is the compartment background.
    div_color = grid[divider_rows[0]][0] if divider_rows else grid[0][divider_cols[0]]
    bg_counts = {}
    for r in range(h):
        for c in range(w):
            if r not in divider_rows and c not in divider_cols and grid[r][c] != div_color:
                bg_counts[grid[r][c]] = bg_counts.get(grid[r][c], 0) + 1
    bg = max(bg_counts, key=bg_counts.get)

    row_starts = [0] + [r + 1 for r in divider_rows if r + 1 < h]
    col_starts = [0] + [c + 1 for c in divider_cols if c + 1 < w]

    # Record the colored pattern by its position inside a compartment.
    pattern = {}
    for r in range(h):
        if r in divider_rows:
            continue
        rs = max(s for s in row_starts if s <= r)
        for c in range(w):
            if c in divider_cols:
                continue
            cs = max(s for s in col_starts if s <= c)
            if grid[r][c] != bg and grid[r][c] != div_color:
                pattern[(r - rs, c - cs)] = grid[r][c]

    out = [[bg for _ in range(w)] for _ in range(h)]
    for r in divider_rows:
        out[r] = [div_color] * w
    for c in divider_cols:
        for r in range(h):
            out[r][c] = div_color

    for rs in row_starts:
        for cs in col_starts:
            for (dr, dc), color in pattern.items():
                r, c = rs + dr, cs + dc
                if r < h and c < w and r not in divider_rows and c not in divider_cols:
                    out[r][c] = color
    return out
